const ROUTES: [RegExp, unknown][] = [
  [/^\/api\/queue$/, { items: library }],
  [/^\/api\/usage$/, { usage: { used: 3, limit: 100, plan: "pro" } }],
  [/^\/api\/summaries\/clip-new$/, { summary: library[2] }],
  [/^\/api\/summaries\/[^/]+\/related$/, { clips: [] }],
  [/^\/api\/summaries\/[^/]+$/, { summary: voiceNote }],
  [/^\/api\/coach\/chat$/, { messages: [...chat, ...said], activity: [] }],
  [/^\/api\/coach\/upnext$/, upnext],
  [/^\/api\/coach\/projects$/, { projects }],
  [/^\/api\/coach\/people$/, { people: [person] }],
  [
    /^\/api\/coach\/projects\/[^/]+\/history$/,
    { entries: [{ request, replaced: [] }], progress: [] },
  ],
  [/^\/api\/coach\/batches$/, { batches: [batch] }],
  [
    /^\/api\/coach\/batches\/ready$/,
    {
      requests: [request],
      tasks: [
        fullTask("task-9", "Make the phone number bigger", { requestId: null, state: "done" }),
      ],
    },
  ],
  [/^\/api\/coach\/batches\/candidates$/, { requests: [request], messages: [], tasks: [] }],
  [/^\/api\/coach\/tasks$/, { tasks }],
  [/^\/api\/coach\/tasks\/[^/]+$/, { task: tasks[0] }],
  [/^\/api\/coach\/tasks\/[^/]+\/messages$/, { messages: [] }],
  [/^\/api\/coach\/runs$/, { run: null }],
  [/^\/api\/coach\/people\/[^/]+\/messages$/, { messages: texts, hasMore: false }],
  [/^\/api\/coach\/rules$/, { rules: [] }],
  [
    /^\/api\/coach\/settings$/,
    {
      settings: {
        timezone: "America/New_York",
        timezoneSet: true,
        work: { days: [1, 2, 3, 4, 5], start: "09:00", end: "17:00" },
      },
    },
  ],
  [
    /^\/api\/coach\/health$/,
    { pushTokens: 1, timezoneSet: true, pushOk: true, lastDeliveredAt: null, helperSeenAt: day(0) },
  ],
];

/** Stands in for Cliphy: answers reads with the data above and accepts every write. */
export async function fakeApi(request: Request): Promise<Response> {
  const { pathname } = new URL(request.url);
  const found =
    request.method === "GET" ? ROUTES.find(([pattern]) => pattern.test(pathname)) : null;
  // A new task answers as the real API does, so the screens can open it.
  const made =
    request.method === "POST" && pathname === "/api/coach/tasks"
      ? { task: fullTask("task-new", "New task", { requestId: null }) }
      : null;
  // The digest is a POST that answers with what was found.
  const digest =
    request.method === "POST" && /^\/api\/coach\/people\/[^/]+\/digest$/.test(pathname)
      ? {
          days: 7,
          messageCount: 8,
          groups: [
            {
              name: "Front page",
              items: [
                {
                  title: "Use a new front picture",
                  detail:
                    "Replace the front picture with one of the two she sent, and move the current photo further down the page.",
                  quotes: [
                    {
                      messageId: "message-7",
                      text: "Could one of these be the front picture:",
                      sentAt: day(-0.1),
                      attachments: texts[0].attachments.slice(0, 2),
                    },
                    {
                      messageId: "message-5",
                      text: "Also can the hero photo be the one from the porch shoot",
                      sentAt: day(-0.4),
                      attachments: [],
                    },
                  ],
                  taskId: null,
                  projectId: "project-1",
                  dueDate: date(2),
                  answered: false,
                },
                {
                  title: "Fix the year in the footer",
                  detail: "The footer shows 2025. It should show this year.",
                  quotes: [
                    {
                      messageId: "message-6",
                      text: "And the footer still says 2025",
                      sentAt: day(-0.2),
                      attachments: [],
                    },
                  ],
                  taskId: "task-1",
                  projectId: "project-1",
                  dueDate: null,
                  answered: false,
                },
              ],
            },
            {
              name: "Lighting page",
              items: [
                {
                  title: "Move the sconces up",
                  detail:
                    "Move the sconces higher on the lighting page. She did not say by how much.",
                  quotes: [
                    {
                      messageId: "message-1",
                      text: "Can we move the sconces up a little on the lighting page",
                      sentAt: day(-1),
                      attachments: [],
                    },
                  ],
                  taskId: null,
                  projectId: "project-1",
                  dueDate: null,
                  answered: true,
                },
              ],
            },
          ],
        }
      : null;
  // Saving a note or a recording answers with the clip it became.
  const saved =
    request.method === "POST" && pathname === "/api/notes/voice/upload-url"
      ? { path: "voice/preview/new.webm", signedUrl: "/api/preview-upload", token: "t" }
      : request.method === "POST" && pathname === "/api/notes/voice"
        ? { note: library[2] }
        : request.method === "POST" && pathname === "/api/notes"
          ? { note: library[1] }
          : null;
  const body =
    made ?? digest ?? saved ?? (found ? found[1] : request.method === "GET" ? null : { ok: true });
  return new Response(JSON.stringify(body ?? { error: "Not found" }), {
    status: body ? 200 : 404,
    headers: { "Content-Type": "application/json" },
  });
}
